# -*- coding: utf-8 -*-
"""One-off script: decode official SDG icon PNGs (extracted from hb789.info)
and save them into assets/img/sdg/. Run once, then it can be deleted."""
import base64
import os

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets", "img", "sdg")
os.makedirs(OUT, exist_ok=True)

ICONS = {
"SDG6": "",
"SDG7": "",
"SDG8": "",
"SDG11": "",
"SDG12": "",
"SDG13": "",
"SDG15": "",
"SDG17": "",
}

for alt, b64 in ICONS.items():
    data = base64.b64decode(b64)
    fname = alt.lower() + ".png"
    with open(os.path.join(OUT, fname), "wb") as f:
        f.write(data)
    print("wrote", fname, len(data), "bytes")
